def make(s,name,variant,anatomy,aid,moment,power,pid,setting,sid,camera,choices):
 o=c.read(s);cid=lambda a:[s+'-'+x for x in a.split(',')if x];rq=[{'kind':'anatomy','description':anatomy,'claim_ids':cid(aid)},{'kind':'effect','description':power,'claim_ids':cid(pid)},{'kind':'setting','description':setting,'claim_ids':cid(sid)}]
 prompt=f'''ONE original square premium painterly cinematic Mythics illustration of {name}, {variant}.
ANATOMY: {anatomy} [{', '.join(cid(aid))}]
MOMENT: {moment}
POWER: {power} [{', '.join(cid(pid))}]
SCALE & CAMERA: extreme low angle; {camera}
LIGHT & WEATHER: ONE narrow warm storm-sunset light seam, strong rim light on subject, deep walnut shadows; physical dust/water spray appropriate to the act, never colored magicfog.
SURFACE: richly tactile natural materials: wet skin, coarse opaque cloth, tangled hair/fur, worn wood, dark earth and stone as anatomically appropriate; no plastic.
SETTING: {setting} [{', '.join(cid(sid))}]
MOOD: Reverent overwhelming mythic awe for a living religious tradition. The being must dominate and make the viewer feel like bowing; decisive action, never ordinary animal/human snapshot, cute, static or decorative.
HARD CONSTRAINTS: ONE native square PNG minimum1024x1024; no text/letters/glyphs/logo/frame/border/watermark. No added heads, eyes, arms, legs or fingers; no unsupported horns/wings/chimeraparts. No film/game/anime/comic design. Clothed humanoid torso/hips fullyopaque, no nudity or explicit gore. No generic glow aura/neon/runes/energy ribbons. Source claimIDs never visible text.'''
 o.update(prompt=prompt,request={'prompt':prompt,'transparent_background':False},depicted_variant=variant,visual_requirements=rq,basis_claim_ids=list(dict.fromkeys(sum([r['claim_ids']for r in rq],[]))),aura=power+' ['+', '.join(cid(pid))+']',artistic_choices=choices,worker_agent='lane-A');c.save(s,o)
